"""Make generated identifier positions prefix-portable without rewriting defaults or data literals."""

import ast
from pathlib import Path

from a13n_service.app_database import AppDatabase

# Alembic's autogenerated positional identifier arguments. Columns, expressions and data stay untouched.
_IDENTIFIERS = {
    "create_table": (0,),
    "drop_table": (0,),
    "rename_table": (0, 1),
    "add_column": (0,),
    "drop_column": (0,),
    "alter_column": (0,),
    "create_index": (0, 1),
    "drop_index": (0,),
    "create_primary_key": (0, 1),
    "create_unique_constraint": (0, 1),
    "create_check_constraint": (0, 1),
    "create_foreign_key": (0, 1, 2),
    "drop_constraint": (0, 1),
    "create_table_comment": (0,),
    "drop_table_comment": (0,),
    "f": (0,),
}
_IDENTIFIER_KEYWORDS = {"table_name", "source_table", "referent_table", "constraint_name", "index_name"}


class _PortableNames(ast.NodeTransformer):
    def __init__(self, database: AppDatabase):
        self.database = database

    def identifier(self, node: ast.expr) -> ast.expr:
        if isinstance(node, ast.Constant) and isinstance(node.value, str) and self.database.owns(node.value):
            assert self.database.prefix is not None
            parts = node.value.split(self.database.prefix)[1:]
            expressions = [
                ast.Call(
                    func=ast.Name(id="migration_name", ctx=ast.Load()), args=[ast.Constant(value=part)], keywords=[]
                )
                for part in parts
            ]
            result: ast.expr = expressions[0]
            for expression in expressions[1:]:
                result = ast.BinOp(left=result, op=ast.Add(), right=expression)
            return result
        return node

    def remote_column(self, node: ast.expr) -> ast.expr:
        if isinstance(node, ast.Constant) and isinstance(node.value, str):
            table, separator, column = node.value.rpartition(".")
            if separator and self.database.owns(table):
                return ast.BinOp(
                    left=self.identifier(ast.Constant(value=table)), op=ast.Add(), right=ast.Constant(f".{column}")
                )
        return node

    def visit_Call(self, node: ast.Call) -> ast.Call:
        self.generic_visit(node)
        if not isinstance(node.func, ast.Attribute) or not isinstance(node.func.value, ast.Name):
            return node
        module, method = node.func.value.id, node.func.attr
        if module == "op":
            for position in _IDENTIFIERS.get(method, ()):
                if position < len(node.args):
                    node.args[position] = self.identifier(node.args[position])
            for keyword in node.keywords:
                if keyword.arg in _IDENTIFIER_KEYWORDS:
                    keyword.value = self.identifier(keyword.value)
        elif module in {"sa", "postgresql"}:
            if method == "ForeignKeyConstraint" and len(node.args) > 1 and isinstance(node.args[1], ast.List):
                node.args[1].elts = [self.remote_column(item) for item in node.args[1].elts]
            if method == "ForeignKey" and node.args:
                node.args[0] = self.remote_column(node.args[0])
            if method.endswith("Constraint") or method in {"Index", "Sequence", "Enum", "ENUM"}:
                for keyword in node.keywords:
                    if keyword.arg == "name":
                        keyword.value = self.identifier(keyword.value)
        return node


def make_portable(path: Path, database: AppDatabase) -> None:
    """Only new autogenerated files pass here. Existing revisions and manual SQL are never rewritten."""
    tree = _PortableNames(database).visit(ast.parse(path.read_text()))
    tree.body.insert(
        1, ast.ImportFrom(module="a13n_service.app_database", names=[ast.alias(name="migration_name")], level=0)
    )
    path.write_text(ast.unparse(ast.fix_missing_locations(tree)) + "\n")
